use App\Models\Student;
use App\Models\Course;
use Filament\Actions\Imports\ImportColumn;
use Filament\Actions\Imports\Importer;
use Filament\Actions\Imports\Models\Import;
use Illuminate\Support\Number;
use Filament\Forms\Components\Checkbox;

/**
 * Generated importer for Course Registration rows from CSV/XLSX.
 */
class CourseRegistrationImporter extends Importer
{
    protected static ?string $model = CourseRegistration::class;

    /**
     * Mappable import columns with type casts and rules.
     * @return  array  ImportColumn definitions.
     */
    public static function getColumns(): array
    {
        return [
            ImportColumn::make('id')
                ->label('ID')
                ->numeric()
                ->integer()
                ->ignoreBlankState()
                ->rules(['nullable', 'integer'])
                ->examples(['1', '2'])
                ->exampleHeader('ID'),

            ImportColumn::make('student')
                ->label('nama_penuh')
                ->requiredMapping()
                ->relationship(resolveUsing: ['nama_penuh'])
                ->numeric()
                ->integer()
                ->ignoreBlankState()
                ->rules(['required', 'integer'])
                ->examples(['1', '2'])
                ->exampleHeader('nama_penuh'),

            ImportColumn::make('course')
                ->label('nama_kursus')
                ->requiredMapping()
                ->relationship(resolveUsing: ['nama_kursus'])
                ->numeric()
                ->integer()
                ->ignoreBlankState()
                ->rules(['required', 'integer'])
                ->examples(['1', '2'])
                ->exampleHeader('nama_kursus'),

            ImportColumn::make('tarikh_pendaftaran')
                ->label('Enrolment Date')
                ->ignoreBlankState()
                ->rules(['nullable', 'datetime'])
                ->examples(['2024-01-01 22:56:00', '2024-12-31 22:56:00'])
                ->exampleHeader('Enrolment Date'),

            ImportColumn::make('gred')
                ->label('Grade')
                ->ignoreBlankState()
                ->rules(['nullable', 'max:5'])
                ->examples(['Sample Grade 1', 'Sample Grade 2'])
                ->exampleHeader('Grade'),

            ImportColumn::make('dokumen_lengkap')
                ->label('Documents Complete')
                ->ignoreBlankState()
                ->rules(['nullable', 'max:255'])
                ->examples(['1', '0'])
                ->exampleHeader('Documents Complete'),

            ImportColumn::make('created_at')
                ->label('Created At')
                ->ignoreBlankState()
                ->rules(['nullable', 'datetime'])
                ->examples(['2024-01-01 22:56:00', '2024-12-31 22:56:00'])
                ->exampleHeader('Created At'),

            ImportColumn::make('updated_at')
                ->label('Updated At')
                ->ignoreBlankState()
                ->rules(['nullable', 'datetime'])
                ->examples(['2024-01-01 22:56:00', '2024-12-31 22:56:00'])
                ->exampleHeader('Updated At'),

            ImportColumn::make('deleted_at')
                ->label('Deleted At')
                ->ignoreBlankState()
                ->rules(['nullable', 'datetime'])
                ->examples(['2024-01-01 22:56:00', '2024-12-31 22:56:00'])
                ->exampleHeader('Deleted At'),
        ];
    }

    /**
     * Resolve which record this imported row maps to (generated custom logic).
     * @return  ?CourseRegistration  Resolved record instance.
     */
    public function resolveRecord(): ?CourseRegistration
    {
    
        $student = Student::firstWhere('nama_penuh', $this->data['student'] ?? null);
        $course = Course::firstWhere('nama_kursus', $this->data['course'] ?? null);

        if (!$student || !$course) {
            return null;
        }

        return CourseRegistration::firstOrNew([
            'pelajar_id' => $student->id,
            'kursus_id' => $course->id
        ]);
    }

    /**
     * Notification body shown when the import finishes.
     *
     * @param  Import  $import  The completed import job.
     * @return  string  Human-readable completion summary.
     */
    public static function getCompletedNotificationBody(Import $import): string
    {
        $body = 'Your Course Registration import has completed and ' . Number::format($import->successful_rows) . ' ' . str('row')->plural($import->successful_rows) . ' imported.';

        if ($failedRowsCount = $import->getFailedRowsCount()) {
            $body .= ' ' . Number::format($failedRowsCount) . ' ' . str('row')->plural($failedRowsCount) . ' failed to import.';
        }

        return $body;
    }
    
    /**
     * Extra options form shown before importing (dry run / update existing).
     * @return  array  Form component definitions.
     */
    public static function getOptionsFormComponents(): array
    {
        return [
            Checkbox::make('updateExisting')
                ->label('Update existing records'),
        ];
    }

}
